<script setup>
import {ref,shallowRef,onMounted,onBeforeUnmount,computed} from 'vue';
import {Button,Checkbox,Cell,CellGroup,Slider,Popup,Picker,Radio,RadioGroup} from 'vant';
import 'vant/es/button/style';import 'vant/es/checkbox/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';import 'vant/es/slider/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/radio/style';import 'vant/es/radio-group/style';
const {controller}=defineProps({controller:{type:Object,required:true}}),m=shallowRef(controller.snapshot()),a=controller.actions,board=ref(),picker=ref(''),panel=ref(!window.matchMedia('(max-width:767px)').matches),quizVisible=ref(false),about=ref(false);
const unsubscribe=controller.subscribe(value=>m.value=value);
onMounted(()=>{document.documentElement.classList.add('student-triangle-active');a.attach(board.value);board.value.closest('main').querySelectorAll('.triangle-coordinate [role=slider]').forEach((slider,i)=>slider.setAttribute('aria-label',i?'竖直位置 y':'水平位置 x'));});onBeforeUnmount(()=>{unsubscribe();a.attach(null);document.documentElement.classList.remove('student-triangle-active');});
const shapeNames={acute:'锐角',right:'直角',obtuse:'钝角',equilateral:'等边'};
const columns=computed(()=>picker.value==='vertex'?['A','B','C'].map(v=>({text:v,value:v})):picker.value==='shape'?Object.entries(shapeNames).map(([value,text])=>({text,value})):[.5,1,2].map(value=>({text:value+'×',value})));
const formula=computed(()=>({incenter:'r = 2S / (a + b + c) = S / s（s 为半周长）',circumcenter:'R = abc / (4S)',centroid:'G = (A + B + C) / 3；AG : GM = 2 : 1',orthocenter:'H = A + B + C − 2O（顶点位置向量）'})[m.value.activeKey]||'');
function selected({selectedValues}){a[picker.value](selectedValues[0]);picker.value='';}
function coordinateKey(axis,event){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();const current=m.value.points[m.value.vertex][axis],max=axis==='x'?980:680,delta=(event.shiftKey?10:1)*(['ArrowLeft','ArrowDown'].includes(event.key)?-1:1);a.coordinate(axis,event.key==='Home'?20:event.key==='End'?max:current+delta);}
</script>
<template><main class="student-triangle-centers"><nav class="triangle-nav"><Button tag="a" :href="m.backHref" icon="arrow-left">三角形实验室</Button><Button class="triangle-menu" aria-label="显示学习面板" @click="panel=!panel">☰</Button><div class="triangle-brand"><b>▲</b><span><strong>三角形的四心</strong><small>内心 · 外心 · 重心 · 垂心</small></span></div><div class="triangle-actions"><Button @click="a.reset">重置</Button><Button @click="a.random">随机</Button><Button icon="expand-o" aria-label="切换全屏" @click="a.fullscreen"/><Button icon="info-o" aria-label="四心操作说明" @click="about=true"/></div></nav><header><p>数学 · 动手观察</p><h1>三角形的四心</h1><p>拖动顶点 A、B、C，观察内心、外心、重心与垂心怎样变化。</p></header>
 <section class="triangle-workspace"><div class="triangle-visual"><svg ref="board" class="triangle-board" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="拖动三角形顶点，观察四心位置和辅助线" @pointerdown="a.down" @pointermove="a.move" @pointerup="a.up" @pointercancel="a.up" @lostpointercapture="a.up" @keydown="a.key"/><div class="triangle-toolbar"><p class="triangle-type" aria-live="polite">{{m.triangleType}}</p><div class="triangle-actions"><Checkbox aria-label="顶点标签" :model-value="m.labels" @update:model-value="value=>a.option('labels',value)">顶点标签</Checkbox><Checkbox aria-label="欧拉线" :model-value="m.euler" @update:model-value="value=>a.option('euler',value)">欧拉线</Checkbox><Checkbox aria-label="中点三角形" :model-value="m.medial" @update:model-value="value=>a.option('medial',value)">中点三角形</Checkbox></div><CellGroup><Cell title="典型形状" :value="shapeNames[m.shape]" is-link @click="picker='shape'"/><Cell title="演示速度" :value="m.speed+'×'" is-link @click="picker='speed'"/></CellGroup><div class="triangle-actions"><Button @click="a.step">单步</Button><Button type="primary" :aria-pressed="m.playing" @click="a.play">{{m.playing?'停止演示':'动态演示'}}</Button><Button :aria-expanded="panel" @click="panel=!panel">学习面板</Button></div><Button @click="quizVisible=!quizVisible;a.quiz(quizVisible)">小测验</Button><p role="status" aria-live="polite">{{m.status}}</p></div></div>
 <aside v-show="panel" class="triangle-learning"><section class="triangle-goals"><h2>学习目标</h2><Checkbox v-for="(goal,i) in m.goals" :key="goal.title" :aria-label="goal.title" :model-value="goal.done" @update:model-value="value=>a.goal(i,value)">{{goal.title}}</Checkbox></section><h2>选择显示的心</h2><div v-for="center in m.centers" :key="center.key" class="triangle-center-row" :class="{'is-active':m.activeKey===center.key}"><Checkbox :model-value="center.on" :aria-label="'显示'+center.name" @update:model-value="value=>a.center(center.key,value)"/><Button :aria-pressed="m.activeKey===center.key" @click="a.center(center.key)"><span class="center-dot" :style="{background:center.color}"/>{{center.name}} {{center.sym}}<small>{{center.en}}</small></Button></div><section class="triangle-explanation"><h3>{{m.info?m.info.name+' · '+m.info.en:'作图原理'}}</h3><div v-if="m.info" v-html="m.info.desc"/><p v-else>选择一个心，查看它由哪三条线相交得到。</p><p class="triangle-formula">{{formula}}</p></section><h2>移动顶点</h2><Cell title="选择顶点" :value="m.vertex" is-link @click="picker='vertex'"/><div class="triangle-coordinate"><label :id="'triangle-x-label'">水平位置 x：{{Math.round(m.points[m.vertex].x)}}</label><Slider :model-value="m.points[m.vertex].x" :min="20" :max="980" :step="1" aria-labelledby="triangle-x-label" @keydown="event=>coordinateKey('x',event)" @update:model-value="value=>a.coordinate('x',value)"/></div><div class="triangle-coordinate"><label id="triangle-y-label">竖直位置 y：{{Math.round(m.points[m.vertex].y)}}</label><Slider :model-value="m.points[m.vertex].y" :min="20" :max="680" :step="1" aria-labelledby="triangle-y-label" @keydown="event=>coordinateKey('y',event)" @update:model-value="value=>a.coordinate('y',value)"/></div><p class="triangle-help">也可用 Tab 聚焦画布顶点，按方向键移动；Shift + 方向键每次移动 10 单位。</p><section v-if="m.geometry" class="triangle-data"><h2>实时数据</h2><p>边长 a : b : c ≈ {{(m.geometry.a/100).toFixed(2)}} : {{(m.geometry.b/100).toFixed(2)}} : {{(m.geometry.c/100).toFixed(2)}}</p><p>面积 S ≈ {{(m.geometry.area/10000).toFixed(2)}}</p><p>内切圆 r ≈ {{(m.geometry.r/100).toFixed(2)}}</p><p>外接圆 R ≈ {{(m.geometry.R/100).toFixed(2)}}</p><small>以 100 像素换算为 1 单位，仅作相对展示。</small></section></aside></section>
 <section v-show="quizVisible&&m.quizOpen" class="triangle-quiz"><header class="triangle-quiz-heading"><h2>小测验</h2><Button v-if="m.quizOpen" icon="cross" aria-label="关闭小测验" @click="a.quiz(false)"/><Button v-else @click="a.quiz(true)">打开小测验</Button></header><div v-if="m.quizOpen" class="triangle-quiz-grid"><article v-for="(q,i) in m.quiz" :key="q.q"><h3>{{i+1}}. {{q.q}}</h3><RadioGroup :model-value="q.selected" :disabled="q.selected!==undefined" :aria-label="'第'+(i+1)+'题'" @update:model-value="value=>a.answer(i,value)"><Radio v-for="(option,j) in q.opts" :key="option" :aria-label="option" :name="j">{{option}}</Radio></RadioGroup><p v-if="q.selected!==undefined" :class="q.selected===q.a?'triangle-correct':'triangle-error'">{{q.selected===q.a?'答对了！':'再巩固一下。正确答案：'+q.opts[q.a]}} {{q.tip}}</p></article></div></section>
 <Popup :show="!!picker" @update:show="value=>!value&&(picker='')" position="bottom" round class="triangle-popup"><header><h2>{{picker==='vertex'?'选择顶点':picker==='shape'?'典型形状':'演示速度'}}</h2><Button icon="cross" aria-label="关闭选择" @click="picker=''"/></header><Picker :columns="columns" @confirm="selected"><template #cancel><Button icon="cross" aria-label="关闭选择" @click="picker=''"/></template></Picker></Popup><Popup v-model:show="about" round class="triangle-about"><header><h2>观察四心</h2><Button icon="cross" aria-label="关闭操作说明" @click="about=false"/></header><p>拖动顶点或调整坐标，勾选需要显示的心，点击名称查看作图原理。</p><p>非等边三角形 O、G、H 共线且 OG : GH = 1 : 2；等边三角形四心重合，欧拉线方向不唯一。</p><p>顶点重合或近乎共线时，四心暂不定义。试着恢复一个非退化的三角形。</p></Popup>
</main></template>
